"""Cross-tenant harness generator per Doc 04 §13.7.

Walks the Django model registry once at collection time, discovers all models
belonging to apps listed in settings.TENANT_APPS, resolves their <Model>Factory,
and generates isolation test cases.
"""

from __future__ import annotations

import importlib

import factory
from django.apps import apps
from django.conf import settings
from django.db import models

# Explicit exclusion list for tenant models that cannot or should not be
# generated by the automated isolation suite. Empty by default.
# Format: {"app_label.ModelName": "Detailed justification per Doc 04 §13.7"}
# Note: LAB-54 formalises this dictionary into the reviewed allow-list and merge gate.
EXCLUDED_MODELS: dict[str, str] = {
    # Django framework models pulled into TENANT_APPS by LAB-5 (KAN-37) so
    # their tables exist per tenant. They are not LabFlow domain models and
    # have no <Model>Factory by design; isolation of domain models is what
    # this harness parameterizes. LAB-54 formalises the reviewed allow-list.
    "auth.Permission": (
        "Django framework model in TENANT_APPS (LAB-5), not a domain model"
    ),
    "auth.Group": "Django framework model in TENANT_APPS (LAB-5), not a domain model",
    "auth.User": "Django framework model in TENANT_APPS (LAB-5), not a domain model",
    "contenttypes.ContentType": (
        "Django framework model in TENANT_APPS (LAB-5), not a domain model"
    ),
}


def get_tenant_app_labels() -> set[str]:
    """
    Retrieve normalized app labels for all applications listed in
    settings.TENANT_APPS.
    """
    tenant_apps_config = getattr(settings, "TENANT_APPS", [])
    labels: set[str] = set()

    for app_entry in tenant_apps_config:
        # Handle full paths (e.g. 'apps.patients') or short labels (e.g. 'patients')
        short_name = app_entry.split(".")[-1]
        try:
            app_config = apps.get_app_config(short_name)
            labels.add(app_config.label)
        except LookupError:
            try:
                app_config = apps.get_app_config(app_entry)
                labels.add(app_config.label)
            except LookupError:
                labels.add(short_name)

    return labels


def get_tenant_models() -> list[type[models.Model]]:
    """
    Walk Django app registry and return all non-abstract managed models in TENANT_APPS.

    Execution is O(M) over the registered models.
    """
    tenant_labels = get_tenant_app_labels()
    tenant_models: list[type[models.Model]] = []

    for model in apps.get_models():
        if model._meta.abstract:
            continue
        if model._meta.app_label in tenant_labels:
            tenant_models.append(model)

    return tenant_models


def is_model_excluded(model: type[models.Model]) -> tuple[bool, str]:
    """
    Check if a model is explicitly registered in EXCLUDED_MODELS with justification.
    """
    model_key = f"{model._meta.app_label}.{model.__name__}"
    if model_key in EXCLUDED_MODELS:
        return True, EXCLUDED_MODELS[model_key]
    return False, ""


def get_factory_for_model(
    model: type[models.Model],
) -> type[factory.django.DjangoModelFactory] | None:
    """Resolve <Model>Factory for the given model from tests.factories.

    Searches:
    1. Direct attribute on tests.factories (e.g. tests.factories.PatientFactory).
    2. App-specific factory submodule (e.g. tests.factories.patients.PatientFactory).
    """
    factory_name = f"{model.__name__}Factory"

    # 1. Search root factory package
    try:
        factories_pkg = importlib.import_module("tests.factories")
        if hasattr(factories_pkg, factory_name):
            candidate = getattr(factories_pkg, factory_name)
            if issubclass(candidate, factory.Factory):
                return candidate
    except ModuleNotFoundError:
        pass

    # 2. Search app-specific submodule in tests.factories.<app_label>
    submodule_path = f"tests.factories.{model._meta.app_label}"
    try:
        app_factories = importlib.import_module(submodule_path)
        if hasattr(app_factories, factory_name):
            candidate = getattr(app_factories, factory_name)
            if issubclass(candidate, factory.Factory):
                return candidate
    except ModuleNotFoundError:
        pass

    return None


def validate_tenant_model_factory(
    model: type[models.Model],
) -> type[factory.django.DjangoModelFactory]:
    """
    Resolve factory for tenant model or fail loudly naming the model per Doc 04 §13.7.
    """
    excluded, reason = is_model_excluded(model)
    if excluded:
        raise ValueError(
            f"Model '{model._meta.label}' is explicitly excluded: {reason}"
        )

    factory_cls = get_factory_for_model(model)
    if factory_cls is None:
        raise RuntimeError(
            f"Missing factory for tenant model '{model._meta.label}' "
            f"({model.__name__}). Expected factory named '{model.__name__}Factory' "
            f"in 'tests.factories' per Doc 09 §9.4 and Doc 04 §13.7. "
            f"A tenant model without a factory is a review blocker."
        )

    return factory_cls
